const request = $json ?? {};
const body = (request && typeof request === 'object' && request.body && typeof request.body === 'object') ? request.body : request;
const env = $env ?? {};

function trimSlash(v) {
  return String(v || '').replace(/\/+$/, '');
}

function pickEnv(...keys) {
  for (const k of keys) {
    const v = env?.[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v);
  }
  return '';
}

function pickBody(...keys) {
  for (const k of keys) {
    const v = body?.[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v);
  }
  return '';
}

function isTruthy(v) {
  const raw = String(v ?? '').trim().toLowerCase();
  return ['1', 'true', 'yes', 'y', 'on'].includes(raw);
}

function toInt(v, fallback) {
  const n = Number.parseInt(String(v ?? ''), 10);
  return Number.isFinite(n) ? n : fallback;
}

function required(v, name) {
  if (!String(v ?? '').trim()) {
    throw new Error(`${name} is required`);
  }
  return v;
}

const realm = String(
  pickBody('realm', 'N8N_REALM') ||
  pickEnv('N8N_REALM') ||
  pickEnv('N8N_OBSERVER_REALM') ||
  'default'
).trim() || 'default';

const gitlabBaseUrl = trimSlash(
  pickBody('gitlab_base_url', 'GITLAB_BASE_URL', 'N8N_GITLAB_BASE_URL') ||
  pickEnv('N8N_GITLAB_BASE_URL', 'GITLAB_BASE_URL', 'GITLAB_URL', 'SERVICE_URL_GITLAB')
);

const gitlabApiBaseUrl = trimSlash(
  pickBody('gitlab_api_base_url', 'GITLAB_API_BASE_URL', 'N8N_GITLAB_API_BASE_URL') ||
  pickEnv('N8N_GITLAB_API_BASE_URL', 'GITLAB_API_BASE_URL') ||
  (gitlabBaseUrl ? `${gitlabBaseUrl}/api/v4` : '')
);

const gitlabToken = pickEnv('N8N_GITLAB_TOKEN', 'GITLAB_TOKEN', 'GITLAB_ADMIN_TOKEN');

const groupFullPath = pickBody('gitlab_group_full_path') || pickEnv('N8N_GITLAB_GROUP_FULL_PATH', 'GITLAB_GROUP_FULL_PATH', 'GROUP_FULL_PATH');
const defaultProjectPath = groupFullPath ? `${groupFullPath}/general-management` : `${realm}/general-management`;

const projectRef = (
  pickBody('gitlab_project_id', 'gitlab_project_path', 'GITLAB_PROJECT_ID', 'GITLAB_PROJECT_PATH') ||
  pickEnv('N8N_GITLAB_GENERAL_MANAGEMENT_PROJECT_ID', 'GITLAB_GENERAL_MANAGEMENT_PROJECT_ID') ||
  pickEnv('N8N_GITLAB_GENERAL_MANAGEMENT_PROJECT_PATH', 'GITLAB_GENERAL_MANAGEMENT_PROJECT_PATH') ||
  pickBody('N8N_GITLAB_PROJECT_ID', 'N8N_GITLAB_PROJECT_PATH') ||
  pickEnv('N8N_GITLAB_PROJECT_ID', 'GITLAB_PROJECT_ID', 'N8N_GITLAB_PROJECT_PATH', 'GITLAB_PROJECT_PATH') ||
  defaultProjectPath
);

const cirLabel = String(pickBody('cir_label') || pickEnv('ITSM_CIR_LABEL') || 'ITSM/継続的改善').trim() || 'ITSM/継続的改善';
const approvedLabel = String(pickBody('approved_label', 'status_label') || pickEnv('ITSM_CIR_APPROVED_LABEL') || '状態/Approved').trim() || '状態/Approved';

const issueState = String(pickBody('issue_state') || pickEnv('ITSM_CIR_ISSUE_STATE') || 'opened').trim() || 'opened';
const perPage = Math.max(1, Math.min(100, toInt(pickBody('per_page') || pickEnv('ITSM_CIR_PER_PAGE') || 50, 50)));
const maxPages = Math.max(1, Math.min(50, toInt(pickBody('max_pages') || pickEnv('ITSM_CIR_MAX_PAGES') || 10, 10)));
const dryRun = isTruthy(pickBody('dry_run') || pickEnv('ITSM_CIR_DRY_RUN') || 'false');

required(gitlabApiBaseUrl, 'GITLAB_API_BASE_URL');
required(gitlabToken, 'GITLAB_TOKEN');
required(projectRef, 'GITLAB_GENERAL_MANAGEMENT_PROJECT_(ID|PATH)');

return [{
  json: {
    realm,
    dry_run: dryRun,
    gitlab_api_base_url: gitlabApiBaseUrl,
    gitlab_token: gitlabToken,
    project_ref: projectRef,
    filters: {
      cir_label: cirLabel,
      approved_label: approvedLabel,
      labels_and: [cirLabel, approvedLabel],
      issue_state: issueState
    },
    pagination: { per_page: perPage, max_pages: maxPages },
    received: {
      gitlab_project_id: body?.gitlab_project_id ?? null,
      gitlab_project_path: body?.gitlab_project_path ?? null
    }
  }
}];

const req = $json ?? {};

function isNumeric(v) {
  return typeof v === 'number' || (typeof v === 'string' && /^[0-9]+$/.test(v));
}

function encProjectRef(ref) {
  const r = String(ref ?? '').trim();
  return isNumeric(r) ? r : encodeURIComponent(r);
}

function safeString(v) {
  const s = (v === undefined || v === null) ? '' : String(v);
  return s;
}

function redact(value) {
  if (!value) return '';
  return '***';
}

const dryRun = Boolean(req.dry_run);
if (dryRun) {
  return [{
    json: {
      ...req,
      fetch: {
        skipped: true,
        reason: 'dry_run'
      },
      issues: []
    }
  }];
}

const apiBase = safeString(req.gitlab_api_base_url).replace(/\/+$/, '');
const token = safeString(req.gitlab_token);
const projectRef = safeString(req.project_ref);
const labels = Array.isArray(req?.filters?.labels_and) ? req.filters.labels_and : [];
const issueState = safeString(req?.filters?.issue_state || 'opened');
const perPage = Number(req?.pagination?.per_page || 50);
const maxPages = Number(req?.pagination?.max_pages || 10);

const encodedProject = encProjectRef(projectRef);
const issuesUrl = `${apiBase}/projects/${encodedProject}/issues`;

async function fetchPage(page) {
  return await $httpRequest({
    method: 'GET',
    url: issuesUrl,
    qs: {
      labels: labels.join(','),
      state: issueState,
      per_page: perPage,
      page
    },
    headers: {
      'PRIVATE-TOKEN': token
    }
  });
}

const all = [];
let page = 1;
while (page <= maxPages) {
  const items = await fetchPage(page);
  if (!Array.isArray(items) || items.length === 0) break;
  for (const it of items) all.push(it);
  if (items.length < perPage) break;
  page += 1;
}

return [{
  json: {
    ...req,
    gitlab_token: redact(req.gitlab_token),
    fetch: {
      skipped: false,
      pages: page,
      fetched: all.length,
      url: issuesUrl
    },
    issues: all
  }
}];

const payload = $json ?? {};
const issues = Array.isArray(payload.issues) ? payload.issues : [];

function uniq(list) {
  const out = [];
  const seen = new Set();
  for (const v of list) {
    const k = String(v ?? '').trim();
    if (!k) continue;
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(k);
  }
  return out;
}

function extractUsecaseIds(text) {
  const s = String(text ?? '');
  const m = s.match(/\bUC-[A-Z0-9][A-Z0-9-]{2,}\b/g);
  return m ? m : [];
}

function extractUsecaseLines(text) {
  const s = String(text ?? '');
  const lines = s.split(/\r?\n/);
  const out = [];
  for (const line of lines) {
    const trimmed = line.trim();
    if (!trimmed) continue;
    if (/^[-*]\s*UC-[A-Z0-9]/.test(trimmed)) {
      out.push(trimmed.replace(/^[-*]\s*/, '- '));
      continue;
    }
  }
  return out;
}

const issueSummaries = issues.map((issue) => {
  const title = issue?.title ?? '';
  const description = issue?.description ?? '';
  const ids = uniq([...extractUsecaseIds(title), ...extractUsecaseIds(description)]);
  const lines = uniq(extractUsecaseLines(description));
  const labels = Array.isArray(issue?.labels) ? issue.labels : [];
  return {
    id: issue?.id ?? null,
    iid: issue?.iid ?? null,
    title,
    web_url: issue?.web_url ?? issue?.url ?? null,
    state: issue?.state ?? null,
    labels,
    created_at: issue?.created_at ?? null,
    updated_at: issue?.updated_at ?? null,
    usecase_ids: ids,
    usecase_lines: lines
  };
});

const allIds = uniq(issueSummaries.flatMap((i) => i.usecase_ids || []));
const allLines = uniq(issueSummaries.flatMap((i) => i.usecase_lines || []));

return [{
  json: {
    ok: true,
    realm: payload.realm ?? 'default',
    project_ref: payload.project_ref ?? null,
    filters: payload.filters ?? {},
    pagination: payload.pagination ?? {},
    fetch: payload.fetch ?? {},
    issues_count: issueSummaries.length,
    usecase_ids: allIds,
    usecase_lines: allLines,
    issues: issueSummaries
  }
}];
